import React, { useState } from "react";
import { searchMovies, getMovieDetail } from "../api/movieApi";
import { getPosterFromTMDB } from "../api/tmdbApi"; // 🔹 TMDB 포스터 가져오기 함수 추가

const SearchPage = () => {
  const [query, setQuery] = useState("");
  const [movies, setMovies] = useState([]);
  const [details, setDetails] = useState({});
  const [posters, setPosters] = useState({}); // 🔹 포스터 URL 저장
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");

  const handleSearch = async () => {
    if (!query.trim()) return;

    setLoading(true);
    setErrorMsg("");
    setDetails({});
    setPosters({});

    try {
      const results = await searchMovies(query);
      setMovies(results);

      // 영화 상세정보 + 포스터 병렬로 불러오기
      const combinedPromises = results.map(async (movie) => {
        const [detail, posterUrl] = await Promise.all([
          getMovieDetail(movie.movieCd),
          getPosterFromTMDB(movie.movieNm, movie.openDt),
        ]);
        return { movieCd: movie.movieCd, detail, posterUrl };
      });

      const allData = await Promise.all(combinedPromises);

      const detailMap = {};
      const posterMap = {};
      allData.forEach(({ movieCd, detail, posterUrl }) => {
        detailMap[movieCd] = detail;
        posterMap[movieCd] = posterUrl;
      });

      setDetails(detailMap);
      setPosters(posterMap);

      if (results.length === 0) {
        setErrorMsg("검색 결과가 없습니다.");
      }
    } catch (error) {
      setErrorMsg("영화 검색 중 오류 발생");
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === "Enter") handleSearch();
  };

  return (
    <div className="p-4 max-w-3xl mx-auto">
      <h1 className="text-2xl font-bold mb-4">🎬 영화 검색 (KOFIC + TMDB)</h1>

      <div className="flex gap-2 mb-4">
        <input
          type="text"
          placeholder="영화 제목을 입력하세요"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onKeyDown={handleKeyDown}
          className="border px-3 py-2 flex-1 rounded"
        />
        <button
          onClick={handleSearch}
          className="bg-blue-500 text-white px-4 py-2 rounded"
        >
          검색
        </button>
      </div>

      {loading && <p>🔍 검색 중...</p>}
      {errorMsg && <p className="text-red-500">{errorMsg}</p>}

      <ul className="space-y-4">
        {movies.map((movie) => {
          const detail = details[movie.movieCd] || {};
          const poster = posters[movie.movieCd] || "https://via.placeholder.com/120x170?text=No+Image";

          return (
            <li
              key={movie.movieCd}
              className="border p-4 rounded shadow-sm bg-white flex gap-4"
            >
              <img
                src={poster}
                alt={movie.movieNm}
                className="w-32 h-auto rounded"
              />
              <div>
                <h2 className="text-lg font-bold mb-2">
                  {movie.movieNm} ({movie.movieNmEn || "N/A"})
                </h2>
                <p>
                  <strong>🎬 개봉일:</strong> {movie.openDt || "N/A"}
                </p>
                <p>
                  <strong>🎬 감독:</strong>{" "}
                  {movie.directors?.map((d) => d.peopleNm).join(", ") || "N/A"}
                </p>
                <p>
                  <strong>🎭 장르 (전체):</strong> {movie.genreAlt || "N/A"}
                </p>
                <p>
                  <strong>🌐 국가:</strong> {movie.repNationNm || "N/A"}
                </p>
                <p>
                  <strong>⏱ 상영시간:</strong> {detail.showTm || "정보 없음"}
                </p>
                <p>
                  <strong>👨‍🎤 배우:</strong>{" "}
                  {detail.actors?.map((a) => a.peopleNm).slice(0, 5).join(", ") ||
                    "정보 없음"}
                </p>
                <p>
                  <strong>🔒 관람등급:</strong>{" "}
                  {detail.audits?.[0]?.watchGradeNm || "정보 없음"}
                </p>
              </div>
            </li>
          );
        })}
      </ul>
    </div>
  );
};

export default SearchPage;
